INSERT INTO store_dish(tenant_id,store_id,dish_id,on_sale,sold_out,override_price,sort)
SELECT #{tenant},#{store},p.id,#{onSale},#{soldOut},#{overridePrice},#{sort}
FROM dish p WHERE p.tenant_id=#{tenant} AND p.id=#{id}
ON DUPLICATE KEY UPDATE on_sale=VALUES(on_sale),sold_out=VALUES(sold_out),override_price=VALUES(override_price),sort=VALUES(sort)


INSERT INTO store_setmeal(tenant_id,store_id,setmeal_id,on_sale,sold_out,override_price,sort)
SELECT #{tenant},#{store},p.id,#{onSale},#{soldOut},#{overridePrice},#{sort}
FROM setmeal p WHERE p.tenant_id=#{tenant} AND p.id=#{id}
ON DUPLICATE KEY UPDATE on_sale=VALUES(on_sale),sold_out=VALUES(sold_out),override_price=VALUES(override_price),sort=VALUES(sort)
